import ctypes

class Person:
    def __init__(self):
        self.status = 0

def allocate_person():
    # Allouer un bloc de mémoire de taille sizeof(Person)
    person_ptr = ctypes.POINTER(Person)()
    person_ptr = ctypes.cast(ctypes.malloc(ctypes.sizeof(Person)), ctypes.POINTER(Person))

    # Vérifier si le pointeur est nul
    if person_ptr is None:
        print("Erreur : Impossible d'allouer de la mémoire pour une personne.")
        return None

    # Initialiser la personne (le champ status est déjà 0 par défaut)
    person_ptr.contents.status = 0

    return person_ptr

# Exemple d'utilisation
if __name__ == "__main__":
    person = allocate_person()
    if person:
        print("Personne allouée avec succès, statut =", person.contents.status)

