class Person:
    def __init__(self):
        self.status = 0

def allocate_person():
    """Phân bổ một đối tượng Person và trả về con trỏ (đối tượng) đến nó."""
    return Person()

def free_person(person):
    """Giải phóng bộ nhớ đã phân bổ cho đối tượng Person."""
    # Trong Python, việc giải phóng bộ nhớ được quản lý tự động bởi garbage collector
    # Do đó, ta chỉ cần gán None để đánh dấu đối tượng không còn cần thiết
    person = None
